/**
 * Photography for the home-page hero carousel.
 *
 * Real crews on real jobs — the montage is the proof, so the copy beside it
 * does not have to work as hard. Swap `src` for the company's own photos when
 * they land; the sources and licences are recorded in
 * `public/images/hero/CREDITS.md`.
 *
 * `position` is the CSS `object-position` for that frame. The hero crops hard
 * on narrow viewports, so each value is tuned to keep the worker — not the
 * sky — in the visible band.
 *
 * `blurDataURL` is a 16px encode of the same file, inlined so a slide that has
 * not finished downloading still fades in as colour rather than black.
 */

export type HeroSlide = {
  src: string;
  alt: string;
  kicker: string;
  title: string;
  location: string;
  position: string;
  blurDataURL: string;
};

